import TotalField from "./totalfield.js";

// Cross-instance locale-sync channel. When any localized field on the page
// switches locale (with sync enabled), every other sync-enabled instance follows.
const LOCALE_SYNC_EVENT = 'totalform:locale-sync';

//-----------------------------------------------
// Total CMS Localized Text Field (Pro)
//
// Tab-per-locale interface. One delegated click handler toggles `hidden` on
// panes and `aria-selected` on tabs. getValue() returns a locale-keyed dict
// of all inputs (hidden or not); setValue(dict) distributes values to each
// locale's input.
//-----------------------------------------------
export default class LocalizedTextField extends TotalField {

	constructor(container, settings) {
		super(container, settings);

		// All per-locale inputs in document order (hidden + visible).
		this.localeInputs = Array.from(
			this.container.querySelectorAll('input[data-locale], textarea[data-locale]')
		);

		// Surface changed() on EACH input — base class only listens on the
		// first one, but edits in any tab should mark the form unsaved.
		this.localeInputs.forEach(input => {
			input.addEventListener('input', () => this.changed());
			input.addEventListener('change', () => this.changed());
		});

		this.bindTabSwitching();
		this.trackTabsWidth();

		// Cross-field locale sync — default on, opt-out via `settings.localeSync: false`.
		// When enabled, clicking a tab on one localized field switches every other
		// sync-enabled localized field on the page to the same locale.
		if (this.settings.localeSync !== false) {
			this.bindLocaleSync();
		}

		// Refresh stored value now that getValue() can read all locales.
		this.storedValue = JSON.stringify(this.getValue());
	}

	// The help overlay shares the header row with the locale tabs and is opaque,
	// so it has to stop short of them — and only the browser knows where they
	// begin, since that depends on the configured locales and how wide their
	// labels render. Publish the strip's width for the stylesheet to inset by,
	// and keep it current: fonts load late, and the header wraps the tabs onto
	// their own row when it is narrow, where there is nothing to avoid and the
	// overlay may use the full width again.
	trackTabsWidth() {
		const tabs  = this.container.querySelector('.locale-tabs');
		const label = this.container.querySelector('.localized-header > label');
		if (!tabs || !label) return;

		const publish = () => {
			const sameRow = Math.abs(tabs.offsetTop - label.offsetTop) < 2;
			const width   = sameRow ? Math.ceil(tabs.getBoundingClientRect().width) : 0;
			this.container.style.setProperty('--locale-tabs-width', `${width}px`);
		};

		publish();

		if (typeof ResizeObserver !== 'undefined') {
			this.tabsObserver = new ResizeObserver(publish);
			this.tabsObserver.observe(tabs);
			this.tabsObserver.observe(this.container);
		}
	}

	bindLocaleSync() {
		this.localeSyncHandler = (e) => {
			if (!e.detail || e.detail.source === this) return;
			// Skip the broadcast on the receiver to avoid loops; the originating
			// field already handled the announcement.
			this.switchToLocale(e.detail.locale, { broadcast: false });
		};
		document.addEventListener(LOCALE_SYNC_EVENT, this.localeSyncHandler);
	}

	bindTabSwitching() {
		this.container.addEventListener('click', e => {
			const tab = e.target.closest('[data-locale-tab]');
			if (!tab || !this.container.contains(tab)) return;
			e.preventDefault();
			this.switchToLocale(tab.dataset.localeTab);
		});

		// Arrow-key navigation between tabs (Left/Right). Per WAI-ARIA
		// tablist pattern. Keeps the field usable without a mouse.
		this.container.addEventListener('keydown', e => {
			const tab = e.target.closest('[data-locale-tab]');
			if (!tab || !this.container.contains(tab)) return;
			if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight') return;
			e.preventDefault();

			const tabs = Array.from(this.container.querySelectorAll('[data-locale-tab]'));
			const idx  = tabs.indexOf(tab);
			const next = e.key === 'ArrowRight'
				? tabs[(idx + 1) % tabs.length]
				: tabs[(idx - 1 + tabs.length) % tabs.length];
			this.switchToLocale(next.dataset.localeTab);
			next.focus();
		});
	}

	switchToLocale(locale, options = {}) {
		// Bail if this field has no tab for the requested locale — fields can
		// disagree (e.g. an extension renders one with a custom locale set).
		const tabs = this.container.querySelectorAll('[data-locale-tab]');
		const hasLocale = Array.from(tabs).some(t => t.dataset.localeTab === locale);
		if (!hasLocale) return;

		tabs.forEach(t => {
			const isActive = t.dataset.localeTab === locale;
			t.setAttribute('aria-selected', isActive ? 'true' : 'false');
			t.tabIndex = isActive ? 0 : -1;
			t.classList.toggle('active', isActive);
		});
		this.container.querySelectorAll('[data-locale-pane]').forEach(p => {
			p.hidden = p.dataset.localePane !== locale;
		});

		// Subclass hook — LocalizedStyledTextField uses this to nudge the
		// matching Tiptap instance so its layout settles.
		this.onLocaleSwitched?.(locale);

		// Broadcast to peer fields unless we're the receiver of a sync event.
		if (options.broadcast !== false && this.settings.localeSync !== false) {
			document.dispatchEvent(new CustomEvent(LOCALE_SYNC_EVENT, {
				detail: { locale, source: this },
			}));
		}
	}

	/** Return the locale-keyed dict of values. */
	getValue() {
		const out = {};
		this.localeInputs.forEach(input => {
			const code = input.dataset.locale;
			if (code) out[code] = input.value ?? '';
		});
		return out;
	}

	/** Accept a dict and distribute values; missing locales become empty strings. */
	setValue(value) {
		const dict = (value && typeof value === 'object') ? value : {};
		this.localeInputs.forEach(input => {
			const code = input.dataset.locale;
			if (code) input.value = dict[code] ?? '';
		});
		this.changed();
	}

	// Override changed() to compare stringified dicts since getValue() returns an object.
	changed() {
		if (this.input) this.input.setCustomValidity("");
		this.container.classList.remove("error");

		const current = JSON.stringify(this.getValue());
		if (this.storedValue === current) return;

		this.storedValue = current;
		this.container.classList.add("unsaved");

		if (this.isSubField()) {
			this.dispatcher.dispatchEvent("subfield-change", { field: this });
			return;
		}
		this.dispatcher.dispatchEvent("field-change", { field: this });
	}

	schema() {
		return {
			"type"  : "localizedtext",
			"field" : "localizedtext"
		};
	}
}
